({ self, context, actions }) {
          const submission = await actions.settleSubmission({ id: self.submissionId, outcome: :accepted });
          await actions.completeTask({ id: submission.taskId }, { ...context, completion: { rule: "review-accepted", submissionId: submission.id } });
        }

({ self, actions }) {
          const submission = await actions.settleSubmission({ id: self.submissionId, outcome: :returned });
          await actions.touchTask({ id: submission.taskId });
        }

({ self, tx, actions }) {
          const live = claimToRelease(await tx.readClaim({ filter: { taskId: { eq: self.taskId } } }), now());
          if (live) await actions.endClaim({ id: live.id, outcome: :released, reason: "submitted" });
          await actions.touchTask({ id: self.taskId });
        }

({ self, actions }) {
          await actions.touchTask({ id: self.taskId });
        }

({ self, tx, actions }) {
          for (const claim of openClaims(await tx.readClaim({ filter: { taskId: { eq: self.id } } })))
            await actions.endClaim({ id: claim.id, outcome: :revoked, reason: "task canceled" });
          for (const submission of await tx.readSubmission({ filter: { taskId: { eq: self.id }, state: { eq: :pending } } }))
            await actions.settleSubmission({ id: submission.id, outcome: :withdrawn });
        }

({ self, before, input, actor, context, tx, actions }) {
          let submission: string | null = null;
          let rule: "review-accepted" | "performer-is-reviewer" | "review-waived" = "review-accepted";
          if (context.completion) submission = context.completion.submissionId;
          else {
            rule = completionRule(actor.id, await reviewerFor(tx, self));
            if (input.summary != null || input.evidence != null) {
              const recorded = await actions.recordAcceptedSubmission({ task: self.id, summary: input.summary ?? null, evidence: input.evidence ?? [], fence: input.fence ?? null, taskVersion: before.version });
              submission = recorded.id;
            } else {
              const own = ownPending(await tx.readSubmission({ filter: { taskId: { eq: self.id }, state: { eq: :pending } } }), actor.id);
              if (own) {
                await actions.settleSubmission({ id: own.id, outcome: :accepted });
                submission = own.id;
              }
            }
          }
          await actions.recordCompletion({ task: self.id, submission, rule });
          const live = claimToRelease(await tx.readClaim({ filter: { taskId: { eq: self.id } } }), now());
          if (live) await actions.endClaim({ id: live.id, outcome: :released, reason: "completed" });
        }

({ self, input, tx, actions }) {
          const current = currentAssignment(await tx.readAssignment({ filter: { taskId: { eq: self.id }, endedAt: { nil: true } } }));
          if (current) {
            if (current.assigneeId !== input.assignee)
              for (const claim of openClaims(await tx.readClaim({ filter: { taskId: { eq: self.id } } }), current.assigneeId))
                await actions.endClaim({ id: claim.id, outcome: :revoked, reason: "reassigned" });
            await actions.finishAssignment({ id: current.id, reason: :reassigned });
          }
          await actions.startAssignment({ task: self.id, assignee: input.assignee, reviewWaived: input.waiveReview ?? false });
        }

({ self, tx, actions }) {
          const current = currentAssignment(await tx.readAssignment({ filter: { taskId: { eq: self.id }, endedAt: { nil: true } } }));
          if (!current) return;
          for (const claim of openClaims(await tx.readClaim({ filter: { taskId: { eq: self.id } } }), current.assigneeId))
            await actions.endClaim({ id: claim.id, outcome: :revoked, reason: "unassigned" });
          await actions.finishAssignment({ id: current.id, reason: :unassigned });
        }
